SET XACT_ABORT ON;
BEGIN TRANSACTION;
IF OBJECT_ID('dbo.PackagingProjects','U') IS NULL CREATE TABLE dbo.PackagingProjects(
 PackagingProjectId UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,WorkspaceId UNIQUEIDENTIFIER NOT NULL,ContentProjectId UNIQUEIDENTIFIER NOT NULL,MasterVideoVersionId UNIQUEIDENTIFIER NOT NULL,Status NVARCHAR(30) NOT NULL DEFAULT 'IN_PROGRESS',ProgressPercent DECIMAL(5,2) NOT NULL DEFAULT 0,ApprovedPackagingVersionId UNIQUEIDENTIFIER NULL,CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),UpdatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT UQ_PackagingProjects_Project UNIQUE(ContentProjectId),CONSTRAINT FK_PackagingProjects_Project FOREIGN KEY(ContentProjectId) REFERENCES dbo.ContentProjects(ContentProjectId),CONSTRAINT FK_PackagingProjects_Master FOREIGN KEY(MasterVideoVersionId) REFERENCES dbo.MasterVideoVersions(MasterVideoVersionId));
IF OBJECT_ID('dbo.ThumbnailVariants','U') IS NULL CREATE TABLE dbo.ThumbnailVariants(
 ThumbnailVariantId UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,PackagingProjectId UNIQUEIDENTIFIER NOT NULL,VariantCode NVARCHAR(40) NOT NULL,Label NVARCHAR(250) NULL,Headline NVARCHAR(150) NULL,Concept NVARCHAR(MAX) NULL,PromptText NVARCHAR(MAX) NULL,Provider NVARCHAR(120) NULL,Model NVARCHAR(120) NULL,AssetUri NVARCHAR(1000) NULL,PreviewUri NVARCHAR(1000) NULL,Status NVARCHAR(30) NOT NULL DEFAULT 'DRAFT',IsPrimary BIT NOT NULL DEFAULT 0,OverallScore DECIMAL(5,2) NULL,ClarityScore DECIMAL(5,2) NULL,EmotionScore DECIMAL(5,2) NULL,CuriosityScore DECIMAL(5,2) NULL,MobileScore DECIMAL(5,2) NULL,ContrastScore DECIMAL(5,2) NULL,ClickScore DECIMAL(5,2) NULL,CreatedByUserId UNIQUEIDENTIFIER NULL,ApprovedByUserId UNIQUEIDENTIFIER NULL,ApprovedAt DATETIME2 NULL,CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),UpdatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_ThumbnailVariants_Packaging FOREIGN KEY(PackagingProjectId) REFERENCES dbo.PackagingProjects(PackagingProjectId));
IF OBJECT_ID('dbo.MetadataPackages','U') IS NULL CREATE TABLE dbo.MetadataPackages(
 MetadataPackageId UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,PackagingProjectId UNIQUEIDENTIFIER NOT NULL,VersionNumber INT NOT NULL,Platform NVARCHAR(60) NOT NULL DEFAULT 'YouTube',Status NVARCHAR(30) NOT NULL DEFAULT 'DRAFT',PrimaryTitle NVARCHAR(500) NULL,Description NVARCHAR(MAX) NULL,KeywordsJson NVARCHAR(MAX) NULL,TagsJson NVARCHAR(MAX) NULL,HashtagsJson NVARCHAR(MAX) NULL,Category NVARCHAR(120) NULL,Language NVARCHAR(80) NULL,AudienceSetting NVARCHAR(120) NULL,PlaylistName NVARCHAR(250) NULL,LicenseSetting NVARCHAR(120) NULL,PinnedComment NVARCHAR(MAX) NULL,QualityScore DECIMAL(5,2) NULL,CreatedByUserId UNIQUEIDENTIFIER NULL,ApprovedByUserId UNIQUEIDENTIFIER NULL,ApprovedAt DATETIME2 NULL,CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),UpdatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT UQ_MetadataPackages_Version UNIQUE(PackagingProjectId,Platform,VersionNumber),CONSTRAINT FK_MetadataPackages_Packaging FOREIGN KEY(PackagingProjectId) REFERENCES dbo.PackagingProjects(PackagingProjectId));
IF OBJECT_ID('dbo.MetadataTitleVariants','U') IS NULL CREATE TABLE dbo.MetadataTitleVariants(TitleVariantId UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,MetadataPackageId UNIQUEIDENTIFIER NOT NULL,TitleText NVARCHAR(500) NOT NULL,VariantOrder INT NOT NULL,Score DECIMAL(5,2) NULL,IsSelected BIT NOT NULL DEFAULT 0,CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_MetadataTitleVariants_Metadata FOREIGN KEY(MetadataPackageId) REFERENCES dbo.MetadataPackages(MetadataPackageId));
IF OBJECT_ID('dbo.CaptionTracks','U') IS NULL CREATE TABLE dbo.CaptionTracks(CaptionTrackId UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,PackagingProjectId UNIQUEIDENTIFIER NOT NULL,LanguageCode NVARCHAR(20) NOT NULL,LanguageName NVARCHAR(80) NOT NULL,TrackType NVARCHAR(50) NOT NULL,Status NVARCHAR(30) NOT NULL DEFAULT 'NOT_STARTED',CoveragePercent DECIMAL(5,2) NOT NULL DEFAULT 0,SourceVersion NVARCHAR(120) NULL,StorageUri NVARCHAR(1000) NULL,Format NVARCHAR(50) NULL,ApprovedByUserId UNIQUEIDENTIFIER NULL,ApprovedAt DATETIME2 NULL,CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),UpdatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_CaptionTracks_Packaging FOREIGN KEY(PackagingProjectId) REFERENCES dbo.PackagingProjects(PackagingProjectId));
IF OBJECT_ID('dbo.ContentChapters','U') IS NULL CREATE TABLE dbo.ContentChapters(ContentChapterId UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,PackagingProjectId UNIQUEIDENTIFIER NOT NULL,ChapterOrder INT NOT NULL,StartSecond INT NOT NULL,Title NVARCHAR(250) NOT NULL,SceneId UNIQUEIDENTIFIER NULL,Status NVARCHAR(30) NOT NULL DEFAULT 'DRAFT',CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),UpdatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT UQ_ContentChapters_Order UNIQUE(PackagingProjectId,ChapterOrder),CONSTRAINT FK_ContentChapters_Packaging FOREIGN KEY(PackagingProjectId) REFERENCES dbo.PackagingProjects(PackagingProjectId));
IF OBJECT_ID('dbo.PlatformPackages','U') IS NULL CREATE TABLE dbo.PlatformPackages(PlatformPackageId UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,PackagingProjectId UNIQUEIDENTIFIER NOT NULL,Platform NVARCHAR(60) NOT NULL,ContentFormat NVARCHAR(60) NOT NULL,AspectRatio NVARCHAR(20) NULL,DurationSeconds INT NULL,Title NVARCHAR(500) NULL,Description NVARCHAR(MAX) NULL,ThumbnailVariantId UNIQUEIDENTIFIER NULL,CaptionTrackId UNIQUEIDENTIFIER NULL,DerivativeAssetUri NVARCHAR(1000) NULL,SettingsJson NVARCHAR(MAX) NULL,Status NVARCHAR(30) NOT NULL DEFAULT 'PLANNED',PackagingScore DECIMAL(5,2) NULL,CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),UpdatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT UQ_PlatformPackages UNIQUE(PackagingProjectId,Platform,ContentFormat),CONSTRAINT FK_PlatformPackages_Packaging FOREIGN KEY(PackagingProjectId) REFERENCES dbo.PackagingProjects(PackagingProjectId),CONSTRAINT FK_PlatformPackages_Thumbnail FOREIGN KEY(ThumbnailVariantId) REFERENCES dbo.ThumbnailVariants(ThumbnailVariantId),CONSTRAINT FK_PlatformPackages_Caption FOREIGN KEY(CaptionTrackId) REFERENCES dbo.CaptionTracks(CaptionTrackId));
IF OBJECT_ID('dbo.PackagingChecks','U') IS NULL CREATE TABLE dbo.PackagingChecks(PackagingCheckId UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,PackagingProjectId UNIQUEIDENTIFIER NOT NULL,CheckKey NVARCHAR(80) NOT NULL,CheckName NVARCHAR(250) NOT NULL,Severity NVARCHAR(30) NOT NULL,IsBlocking BIT NOT NULL DEFAULT 0,Status NVARCHAR(30) NOT NULL DEFAULT 'NEEDS_REVIEW',Evidence NVARCHAR(MAX) NULL,ResolvedByUserId UNIQUEIDENTIFIER NULL,ResolvedAt DATETIME2 NULL,CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),UpdatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT UQ_PackagingChecks UNIQUE(PackagingProjectId,CheckKey),CONSTRAINT FK_PackagingChecks_Packaging FOREIGN KEY(PackagingProjectId) REFERENCES dbo.PackagingProjects(PackagingProjectId));
IF OBJECT_ID('dbo.PackagingVersions','U') IS NULL CREATE TABLE dbo.PackagingVersions(PackagingVersionId UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,PackagingProjectId UNIQUEIDENTIFIER NOT NULL,VersionNumber INT NOT NULL,Status NVARCHAR(30) NOT NULL DEFAULT 'IN_REVIEW',PrimaryThumbnailVariantId UNIQUEIDENTIFIER NULL,MetadataPackageId UNIQUEIDENTIFIER NULL,ManifestJson NVARCHAR(MAX) NULL,ChangeSummary NVARCHAR(2000) NULL,CreatedByUserId UNIQUEIDENTIFIER NULL,ReviewedByUserId UNIQUEIDENTIFIER NULL,ReviewedAt DATETIME2 NULL,ApprovedByUserId UNIQUEIDENTIFIER NULL,ApprovedAt DATETIME2 NULL,CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT UQ_PackagingVersions UNIQUE(PackagingProjectId,VersionNumber),CONSTRAINT FK_PackagingVersions_Packaging FOREIGN KEY(PackagingProjectId) REFERENCES dbo.PackagingProjects(PackagingProjectId),CONSTRAINT FK_PackagingVersions_Thumbnail FOREIGN KEY(PrimaryThumbnailVariantId) REFERENCES dbo.ThumbnailVariants(ThumbnailVariantId),CONSTRAINT FK_PackagingVersions_Metadata FOREIGN KEY(MetadataPackageId) REFERENCES dbo.MetadataPackages(MetadataPackageId));
COMMIT TRANSACTION;
